void set_bigring( int color, int level = FCLED_NUM, int offset = 0 )
{
    bool inv;
    if( inv = level < 0 ) level = -level;
  
  for(int i=0; i<FCLED_NUM; i++ ) 
  {
    int k = (i+offset)%FCLED_NUM;
    if( inv ) k =  FCLED_NUM - k;
    if( i < level ) leds[k] = color; else leds[k] = 0;
  }
}